<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #fbf9ff;
      --surface: #ffffff;
      --text: #121212;
      --muted: #616173;
      --purple: #7638FA;
      --orange: #FF7A00;
      --pink: #ff4fb0;
      --line: #ece8f6;
      --radius: 20px;
      --shadow: 0 12px 30px rgba(36, 15, 82, 0.08);
      --container: min(1160px, 92vw);
    }

    * { box-sizing: border-box; }

    html, body {
      margin: 0;
      padding: 0;
      font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      background: var(--bg);
      color: var(--text);
      scroll-behavior: smooth;
    }

    a { color: inherit; text-decoration: none; }

    .container { width: var(--container); margin: 0 auto; }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 30;
      backdrop-filter: blur(10px);
      background: rgba(251, 249, 255, 0.86);
      border-bottom: 1px solid rgba(118, 56, 250, 0.08);
    }

    .header-inner {
      min-height: 74px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 18px;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      font-weight: 800;
      font-size: 1.1rem;
    }

    .brand-dot {
      width: 30px;
      height: 30px;
      border-radius: 10px;
      background: linear-gradient(135deg, var(--purple), var(--pink), var(--orange));
      box-shadow: 0 8px 14px rgba(118, 56, 250, 0.35);
    }

    .main-nav {
      display: flex;
      align-items: center;
      gap: 24px;
      color: #2f2f43;
      font-weight: 500;
    }

    .main-nav a { padding: 8px 0; }

    .main-nav a:hover,
    .main-nav a:focus-visible { color: var(--purple); }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 44px;
      border-radius: 999px;
      border: 0;
      padding: 0 18px;
      font-weight: 700;
      cursor: pointer;
    }

    .btn-login {
      background: #111;
      color: #fff;
    }

    .btn-primary {
      background: linear-gradient(135deg, var(--purple), var(--pink));
      color: #fff;
      box-shadow: 0 10px 24px rgba(118, 56, 250, 0.32);
    }

    .btn-store {
      background: #191922;
      color: #fff;
      min-width: 140px;
    }

    .hamburger {
      width: 44px;
      height: 44px;
      border-radius: 12px;
      border: 1px solid var(--line);
      background: #fff;
      display: none;
      align-items: center;
      justify-content: center;
      cursor: pointer;
    }

    .hamburger span,
    .hamburger::before,
    .hamburger::after {
      content: "";
      display: block;
      width: 18px;
      height: 2px;
      background: #222;
      border-radius: 2px;
      position: relative;
      transition: 0.2s ease;
    }

    .hamburger::before { position: absolute; transform: translateY(-6px); }
    .hamburger::after { position: absolute; transform: translateY(6px); }

    .mobile-menu {
      display: none;
      border-top: 1px solid var(--line);
      background: #fff;
    }

    .mobile-menu.open { display: block; }

    .mobile-menu nav {
      width: var(--container);
      margin: 0 auto;
      padding: 14px 0 18px;
      display: grid;
      gap: 4px;
    }

    .mobile-menu a {
      min-height: 44px;
      display: flex;
      align-items: center;
      color: #2d2d41;
      border-radius: 10px;
      padding: 0 12px;
    }

    .mobile-menu a:hover,
    .mobile-menu a:focus-visible { background: #f5f2ff; }

    section { padding: 72px 0; }

    .hero {
      padding-top: 66px;
      overflow: hidden;
    }

    .hero-wrap {
      border-radius: 32px;
      background:
        radial-gradient(1000px 400px at 88% -10%, rgba(255, 122, 0, 0.27), transparent 65%),
        radial-gradient(900px 420px at -10% 10%, rgba(118, 56, 250, 0.23), transparent 65%),
        #fff;
      border: 1px solid #efe9ff;
      box-shadow: var(--shadow);
      padding: clamp(26px, 6vw, 68px);
      display: grid;
      grid-template-columns: 1.2fr 0.8fr;
      gap: clamp(22px, 3vw, 34px);
      align-items: center;
    }

    .hero h1 {
      margin: 0;
      font-size: clamp(2rem, 4.2vw, 3.45rem);
      line-height: 1.06;
      letter-spacing: -0.02em;
      max-width: 17ch;
    }

    .hero p {
      margin: 18px 0 28px;
      color: var(--muted);
      max-width: 52ch;
      font-size: 1.05rem;
      line-height: 1.6;
    }

    .hero-art {
      min-height: 300px;
      border-radius: 24px;
      background:
        linear-gradient(165deg, rgba(118,56,250,0.14), rgba(255,122,0,0.12)),
        linear-gradient(45deg, #ede4ff, #fff6ec 55%, #ffe8f4);
      position: relative;
      isolation: isolate;
    }

    .bubble {
      position: absolute;
      border-radius: 999px;
      filter: blur(0.2px);
    }

    .bubble.one { width: 140px; height: 140px; top: 22px; right: 18px; background: rgba(118,56,250,0.24); }
    .bubble.two { width: 90px; height: 90px; bottom: 38px; left: 26px; background: rgba(255,122,0,0.34); }
    .bubble.three { width: 66px; height: 66px; top: 46%; left: 42%; background: rgba(255,79,176,0.32); }

    .section-head {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 18px;
      margin-bottom: 22px;
    }

    h2 {
      margin: 0;
      font-size: clamp(1.55rem, 3vw, 2.2rem);
      letter-spacing: -0.015em;
    }

    .lede {
      margin: 8px 0 0;
      color: var(--muted);
      line-height: 1.6;
      max-width: 68ch;
    }

    .feature-grid,
    .creator-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 16px;
    }

    .card {
      background: var(--surface);
      border: 1px solid var(--line);
      border-radius: var(--radius);
      padding: 22px;
      box-shadow: 0 8px 20px rgba(26, 14, 50, 0.05);
    }

    .card h3 {
      margin: 0 0 10px;
      font-size: 1.1rem;
    }

    .card p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .card-link {
      margin-top: 14px;
      color: var(--purple);
      font-weight: 700;
      display: inline-flex;
      align-items: center;
      gap: 6px;
    }

    .safety {
      background: linear-gradient(180deg, #f3f8ff, #f9fbff);
      border-top: 1px solid #e6efff;
      border-bottom: 1px solid #e6efff;
    }

    .safety .card {
      background: rgba(255,255,255,0.92);
      border-color: #dbe8ff;
    }

    .tagline-banner {
      padding: 30px 0;
    }

    .tagline-box {
      border-radius: 22px;
      padding: 28px;
      background: linear-gradient(90deg, #201233, #7638fa 45%, #ff7a00);
      color: #fff;
      font-size: clamp(1.05rem, 2.6vw, 1.35rem);
      font-weight: 700;
      text-align: center;
      letter-spacing: 0.01em;
    }

    .news-header-link {
      color: var(--purple);
      font-weight: 700;
      min-height: 44px;
      display: inline-flex;
      align-items: center;
    }

    .news-carousel {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: minmax(260px, 1fr);
      gap: 16px;
      overflow-x: auto;
      overscroll-behavior-x: contain;
      scroll-snap-type: x mandatory;
      padding-bottom: 8px;
      scrollbar-width: thin;
      scrollbar-color: rgba(118,56,250,0.35) transparent;
    }

    .news-carousel::-webkit-scrollbar { height: 8px; }
    .news-carousel::-webkit-scrollbar-thumb {
      background: rgba(118,56,250,0.35);
      border-radius: 999px;
    }

    .news-card {
      scroll-snap-align: start;
      background: #fff;
      border: 1px solid var(--line);
      border-radius: 20px;
      box-shadow: 0 10px 24px rgba(30, 16, 60, 0.06);
      overflow: hidden;
    }

    .thumb {
      height: 150px;
      background: linear-gradient(135deg, #d8c6ff, #ffcda7 52%, #ffd9f0);
      position: relative;
    }

    .thumb::after {
      content: "";
      position: absolute;
      inset: 12px;
      border-radius: 14px;
      border: 2px dashed rgba(255,255,255,0.62);
    }

    .news-content { padding: 16px 16px 18px; }

    .tags {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      margin-bottom: 12px;
    }

    .tag {
      font-size: 0.74rem;
      letter-spacing: 0.02em;
      font-weight: 700;
      color: var(--purple);
      background: #efe8ff;
      padding: 6px 10px;
      border-radius: 999px;
    }

    .news-card h3 {
      font-size: 1rem;
      margin: 0 0 10px;
      line-height: 1.4;
    }

    .date {
      color: #66647a;
      font-size: 0.9rem;
    }

    .cta-download {
      padding-top: 54px;
      padding-bottom: 88px;
    }

    .cta-wrap {
      border-radius: 26px;
      background: #fff;
      border: 1px solid var(--line);
      padding: clamp(24px, 4vw, 42px);
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 18px;
      box-shadow: var(--shadow);
    }

    .cta-wrap h2 { margin-bottom: 6px; }

    .store-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
    }

    footer {
      background: #0f1018;
      color: #f2f3f7;
      padding-top: 54px;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(7, minmax(0, 1fr));
      gap: 18px;
      padding-bottom: 26px;
      border-bottom: 1px solid rgba(255,255,255,0.15);
    }

    .footer-col h4 {
      margin: 0 0 14px;
      font-size: 0.95rem;
      color: #fff;
    }

    .footer-col a {
      display: block;
      color: #c7cada;
      line-height: 1.7;
      font-size: 0.93rem;
      min-height: 32px;
    }

    .footer-col a:hover,
    .footer-col a:focus-visible { color: #fff; }

    .footer-bottom {
      padding: 16px 0 24px;
      display: flex;
      flex-wrap: wrap;
      gap: 12px 18px;
      align-items: center;
      justify-content: space-between;
      color: #c7cada;
      font-size: 0.9rem;
    }

    .socials, .legal {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      align-items: center;
    }

    .social-pill {
      min-height: 32px;
      padding: 0 10px;
      border-radius: 999px;
      border: 1px solid rgba(255,255,255,0.24);
      display: inline-flex;
      align-items: center;
      color: #dde0ec;
      font-size: 0.82rem;
    }

    @media (max-width: 1024px) {
      .hero-wrap { grid-template-columns: 1fr; }
      .hero-art { min-height: 220px; }
      .feature-grid, .creator-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .footer-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); }
    }

    @media (max-width: 760px) {
      .main-nav,
      .header-actions .btn-login { display: none; }
      .hamburger { display: inline-flex; }
      section { padding: 58px 0; }
      .feature-grid,
      .creator-grid,
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .section-head { align-items: flex-start; flex-direction: column; }
      .cta-wrap { flex-direction: column; align-items: flex-start; }
      .news-carousel { grid-auto-columns: minmax(82vw, 1fr); }
    }

    @media (max-width: 520px) {
      .feature-grid,
      .creator-grid,
      .footer-grid { grid-template-columns: 1fr; }
      .header-inner { min-height: 68px; }
      .hero { padding-top: 44px; }
      .tagline-box { text-align: left; }
    }
  </style>
</head>
<body>
  <header class="site-header">
